class Solution {
public:
    bool canThreePartsEqualSum(vector<int>& arr) {
        int total = 0;
        for (int x : arr) total += x;
        if (total % 3 != 0) return false;
        int target = total / 3;
        int count = 0, current = 0;
        for (int x : arr) {
            current += x;
            if (current == target) {
                count++;
                current = 0;
            }
        }
        return count >= 3;
    }
};
